r"""
Crescopus - simpler navigation for Builders, Growers and visitors

  - Logo and Home take a logged-in person to their own Home (the dashboard),
    never the landing page. The landing page is only for visitors.
  - One set of five menu items per role, no burger:
      Builder: Home · Find Growers · My Crescos · Messages · Account
      Grower:  Home · Find Apps · My Crescos · Messages · Account
      Visitor: Find · How it works · Log in  (+ Sign up free button)
    Desktop shows them in the top bar; mobile shows them as a bar along the bottom.
  - Badges: requests on Home, plan/ledger items on My Crescos, unread on Messages.
  - New Messages page listing every conversation, unread first.
  - Plan | Ledger | Messages tabs at the top of each Cresco.
  - "My plans" is now "My Crescos"; Settings is now "Account" and holds Log out.
  - Logged-out visitors see "Sign up to connect" on cards.
  - "Back" link only appears on pages below the main menu items.

HOW TO USE
  1. Save this file in your Crescopus project folder (next to wsgi.py).
  2. In PowerShell, in that folder, with your venv active:
         python apply_navigation.py
  3. No SQL to run.
  4. Any file it replaces is copied first to _backup_apply_navigation\.

It checks each file matches the version on GitHub first. If you've changed
one locally since your last push, it stops without writing anything.
Your .env is never read or changed.
"""
import base64, hashlib, os, shutil, sys

# (path, new content, sha256 of the file it expects to replace or None for a new file)
FILES = [
    ('app/__init__.py', '', 'c9fc2112ffe935d57f337f0ded181f34b85674433acbc7e8b4ac60aa3eea9e73'),
    ('app/partnerships/routes.py', '', '9ea190562d9e6f65c4a273efc4f457b8145676a362b61fd86ffd962bfa0f27b9'),
    ('app/static/css/cresco-ui.css', '', 'ea307c2d600fb1fa672c9c4ecc5eac32841c4da021b51a88d0b3cc5c231adf15'),
    ('app/templates/base.html', '', '298fa3f68d42588fe8d5963677a70cb4c377cf6123e6352b85a24690aec8b837'),
    ('app/templates/browse/_app_popup.html', '', '9bfbb602a0ab24a05e1a187f663781873f4662c65deae759fa681945ebde06a7'),
    ('app/templates/browse/_grower_popup.html', '', '80fbef82181b54a6d056e1ffeb922ce9c82fc9a2423fb192ab9147973713d74b'),
    ('app/templates/dashboard/index.html', '', 'bcba6f3b7cf5b5c7fe2612b028a58101202245aafe87a3fe6e821c271ca6fb73'),
    ('app/templates/ledger/view.html', '', '725717058ea4100f50f1a3fc51352080a640245b9e94b05d3cdb8c43a8320cb9'),
    ('app/templates/partnerships/_cresco_tabs.html', '', None),
    ('app/templates/partnerships/detail.html', '', '75f3e92ce0b477a647c00e4a360a3167059b7b395ff4066289255f4cd1b39527'),
    ('app/templates/partnerships/inbox.html', '', None),
    ('app/templates/plans/index.html', '', '761fe387647d2d82a42f5b5926a6bda656ec29df026b3240bb149418bb0a387a'),
    ('app/templates/plans/view.html', '', '27426271a9d43857b5e31c9ad2b6c1f20bc454a26141dbea0c9e864ab3c3fd10'),
    ('app/templates/settings/index.html', '', '3959972556b76e4ba2500914b3e6b06c3d8277f9c2d01512a510f1f5e7679e0c'),
]
BACKUP = "_backup_apply_navigation"
NEXT = "restart python wsgi.py and try it as a builder, a grower and logged out (on your phone too), then commit and push."

def sha(data):
    return hashlib.sha256(data).hexdigest()

def main():
    root = os.path.dirname(os.path.abspath(__file__))
    if not os.path.isfile(os.path.join(root, "app", "__init__.py")) or not os.path.isfile(os.path.join(root, "wsgi.py")):
        sys.exit("Stopped: put this file in the Crescopus project folder (next to wsgi.py and the app folder), then run it again.")

    # Safety check first: never overwrite local changes we don't know about.
    clashes = []
    for rel, b64, expected in FILES:
        path = os.path.join(root, *rel.split("/"))
        new = base64.b64decode(b64)
        if not os.path.exists(path):
            if expected is not None:
                clashes.append(rel + " (missing)")
            continue
        with open(path, "rb") as fh:
            current = fh.read()
        current_norm = current.replace(b"\r\n", b"\n")
        if current == new or current_norm == new:
            continue
        if expected is None or sha(current_norm) != expected:
            clashes.append(rel)
    if clashes:
        print("Stopped - nothing written. These files differ from the version this update was built from:")
        for c in clashes:
            print("   " + c)
        sys.exit("Push or share your latest changes and ask for the update to be rebuilt.")

    backup = os.path.join(root, BACKUP)
    changed = 0
    for rel, b64, expected in FILES:
        path = os.path.join(root, *rel.split("/"))
        data = base64.b64decode(b64)
        status = "new     "
        if os.path.exists(path):
            with open(path, "rb") as fh:
                current = fh.read()
            if current == data or current.replace(b"\r\n", b"\n") == data:
                print("same     " + rel)
                continue
            dest = os.path.join(backup, *rel.split("/"))
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            shutil.copy2(path, dest)
            status = "updated "
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(data)
        changed += 1
        print(status + " " + rel)
    print("\nDone - %d of %d files written." % (changed, len(FILES)))
    if os.path.isdir(backup):
        print("Originals of replaced files are in " + BACKUP + os.sep)
    if NEXT:
        print("Next: " + NEXT)

if __name__ == "__main__":
    main()
